static void Prepare(const std::string& dir){Reset(dir);PlayerPtr->Credits=1000000;PlayerPtr->Tiberium=0;PlayerPtr->IsToWin=PlayerPtr->IsToLose=PlayerPtr->IsToDie=false;auto bad=HouseClass::As_Pointer(HOUSE_BAD);bad->IsActive=true;bad->IsDefeated=false;for(int i=Anims.Count()-1;i>=0;--i)delete Anims.Ptr(i);}
static int Ions(){int n=0;for(int i=0;i<Anims.Count();++i)if(*Anims.Ptr(i)==ANIM_ION_CANNON)++n;return n;}
static void TickAnims(){std::vector<TARGET> ids;for(int i=0;i<Anims.Count();++i)ids.push_back(Anims.Ptr(i)->As_Target());for(auto id:ids){auto a=As_Animation(id);if(a)a->AI();}++Frame;}
static UnitClass* Bike(const std::string& dir){Prepare(dir);auto b=new UnitClass(UNIT_BIKE,HOUSE_GOOD);Check("place player ion bike",Put(b,Center()));b->Assign_Mission(MISSION_SLEEP);b->Commence();return b;}
static void Reveal(CELL c){Map.Map_Cell(c,PlayerPtr,true);}
static void Civilian(const std::string& dir,StructType type,bool discovered){auto bike=Bike(dir);auto t=new BuildingClass(type,HOUSE_BAD);Check("place enemy civilian building",Put(t,XY_Cell(Cell_X(Coord_Cell(bike->Coord))+7,Cell_Y(Coord_Cell(bike->Coord)))));auto id=t->As_Target();Reveal(Coord_Cell(t->Coord));t->IsDiscoveredByPlayer=discovered;int hp=t->Strength;Campaign_Bike_AI(bike);Check("ion automatically selects enemy civilian building including visible legacy discovery state",Ions()==1);for(int tick=0;tick<250&&Ions();++tick)TickAnims();t=As_Building(id);Check("native ion animation actually damages or destroys the civilian building",!t||!t->IsActive||t->Strength<hp);}
static void Wall(const std::string& dir,OverlayType type,HousesType owner,bool revealed,bool inRange,bool expect){auto bike=Bike(dir);CELL c=XY_Cell(Cell_X(Coord_Cell(bike->Coord))+(inRange?7:11),Cell_Y(Coord_Cell(bike->Coord)));Map[c].Overlay=type;Map[c].OverlayData=0;Map[c].Owner=owner;Map[c].Recalc_Attributes();if(revealed)Reveal(c);bool visible=Map[c].Is_Visible(PlayerPtr);Campaign_Bike_AI(bike);std::printf("WALL type=%d owner=%d visible=%d range=%d ions=%d\n",int(type),int(owner),int(visible),int(inRange),Ions());Check("wall targeting respects hostile ownership, discovery and ten-cell range",Ions()==int(expect));if(expect&&Ions()>0){Check("ion lands on the actual owned wall cell",Coord_Cell(Anims.Ptr(Anims.Count()-1)->Coord)==c);for(int tick=0;tick<250&&Ions();++tick)TickAnims();Check("native ion blast reduces a wall damage stage or destroys it",Map[c].Overlay==OVERLAY_NONE||Map[c].OverlayData>=16);}}
static void CivilianFilters(const std::string& dir,HousesType owner){auto bike=Bike(dir);auto t=new BuildingClass(STRUCT_V01,owner);Check("place non-hostile civilian building",Put(t,XY_Cell(Cell_X(Coord_Cell(bike->Coord))+7,Cell_Y(Coord_Cell(bike->Coord)))));t->IsDiscoveredByPlayer=true;Reveal(Coord_Cell(t->Coord));Campaign_Bike_AI(bike);Check("player and neutral civilian buildings are not enemy auto targets",Ions()==0);}
static void SpecialTypes(const std::string& dir){auto bike=Bike(dir);auto t=new InfantryClass(INFANTRY_DELPHI,HOUSE_BAD);Check("place hostile civilian infantry",Put(t,XY_Cell(Cell_X(Coord_Cell(bike->Coord))+7,Cell_Y(Coord_Cell(bike->Coord)))));t->IsDiscoveredByPlayer=true;Campaign_Bike_AI(bike);Check("hostile civilian infantry is eligible under all-enemy targeting",Ions()==1);}
static void Allies(const std::string& dir){auto bike=Bike(dir);PlayerPtr->Make_Ally(HOUSE_BAD);auto t=new BuildingClass(STRUCT_V01,HOUSE_BAD);Check("place allied-owner civilian building",Put(t,XY_Cell(Cell_X(Coord_Cell(bike->Coord))+7,Cell_Y(Coord_Cell(bike->Coord)))));t->IsDiscoveredByPlayer=true;CELL c=XY_Cell(Cell_X(Coord_Cell(bike->Coord))-7,Cell_Y(Coord_Cell(bike->Coord)));Map[c].Overlay=OVERLAY_BRICK_WALL;Map[c].Owner=HOUSE_BAD;Map[c].OverlayData=0;Reveal(c);Campaign_Bike_AI(bike);Check("allied civilian buildings and concrete walls are excluded",Ions()==0);}
static void ActualLoopRepair(const std::string& dir){Prepare(dir);for(int i=Terrains.Count()-1;i>=0;--i)Terrains.Ptr(i)->Limbo();for(int c=0;c<MAP_CELL_TOTAL;++c)if(Map.In_Radar(c)){Map[c].TType=TEMPLATE_CLEAR1;Map[c].TIcon=0;Map[c].Overlay=OVERLAY_NONE;Map[c].Recalc_Attributes();Reveal(c);}std::vector<TARGET> ids;std::vector<int> before;auto center=Center();std::vector<TechnoClass*> objects={new UnitClass(UNIT_BIKE,HOUSE_GOOD),new UnitClass(UNIT_MTANK,HOUSE_GOOD),new InfantryClass(INFANTRY_E1,HOUSE_GOOD),new AircraftClass(AIRCRAFT_ORCA,HOUSE_GOOD),new BuildingClass(STRUCT_OBELISK,HOUSE_GOOD),new BuildingClass(STRUCT_ATOWER,HOUSE_GOOD),new BuildingClass(STRUCT_POWER,HOUSE_GOOD)};
 for(unsigned i=0;i<objects.size();++i){auto o=objects[i];if(o->What_Am_I()==RTTI_AIRCRAFT)static_cast<AircraftClass*>(o)->Altitude=AircraftClass::FLIGHT_LEVEL;Check("place damaged object in real game logic list",Put(o,XY_Cell(Cell_X(center)+(i%3)*5-5,Cell_Y(center)+(i/3)*5-5)));o->Assign_Mission(MISSION_SLEEP);o->Commence();o->Strength=Campaign_Max_Health(o)-20;ids.push_back(o->As_Target());before.push_back(o->Strength);}
 for(int tick=0;tick<45;++tick){++Frame;Logic.AI();}
 for(unsigned i=0;i<ids.size();++i){auto o=As_Techno(ids[i]);std::printf("LOOP REPAIR kind=%d before=%d after=%d max=%d\n",o?int(o->What_Am_I()):-1,before[i],o?int(o->Strength):-1,o?Campaign_Max_Health(o):-1);Check("actual Logic.AI heals every player object type within three game seconds",o&&o->IsActive&&o->Strength>before[i]&&o->Strength<=Campaign_Max_Health(o));}
 Check("game remains active during full-loop auto-repair verification",GameActive);
}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);for(auto type:{STRUCT_V01,STRUCT_V10,STRUCT_V20,STRUCT_V30})for(bool discovered:{false,true})Civilian(dir,type,discovered);for(auto type:{OVERLAY_BRICK_WALL,OVERLAY_SANDBAG_WALL,OVERLAY_CYCLONE_WALL,OVERLAY_BARBWIRE_WALL,OVERLAY_WOOD_WALL})Wall(dir,type,HOUSE_BAD,true,true,true);Wall(dir,OVERLAY_BRICK_WALL,HOUSE_GOOD,true,true,false);Wall(dir,OVERLAY_BRICK_WALL,HOUSE_NEUTRAL,true,true,false);Wall(dir,OVERLAY_BRICK_WALL,HOUSE_BAD,false,true,false);Wall(dir,OVERLAY_BRICK_WALL,HOUSE_BAD,true,false,false);CivilianFilters(dir,HOUSE_GOOD);CivilianFilters(dir,HOUSE_NEUTRAL);SpecialTypes(dir);Allies(dir);ActualLoopRepair(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
